using System.Collections.Generic;
using UnityEngine;

namespace Game.Client.UI
{
    /// <summary>
    /// Icons of items, skills, statuses, window buttons and emotes: `Resources/Icons/&lt;group&gt;/&lt;Icon id&gt;.png`, where the id is
    /// the `Icon` field of the content definition. Loaded on first use and cached. An id without art gives null: the
    /// caller then shows the name as text, so new content works before its picture is drawn.
    /// The pictures are generated by `tools/IconGen` (see its README).
    /// </summary>
    public sealed class IconLibrary
    {
        private const string Root = "Icons/";
        private const float PixelsPerUnit = 100f;

        private readonly Group _items = new Group("items");
        private readonly Group _skills = new Group("skills");
        private readonly Group _statuses = new Group("statuses");
        private readonly Group _windows = new Group("windows");
        private readonly Group _emotes = new Group("emotes");

        public Sprite Item(string icon) => _items.Get(icon);

        public Sprite Skill(string icon) => _skills.Get(icon);

        public Sprite Status(string icon) => _statuses.Get(icon);

        public Sprite Window(string icon) => _windows.Get(icon);

        public Sprite Emote(string icon) => _emotes.Get(icon);

        /// <summary>One folder of icons; the cache is per folder so that a lookup does not build a path string.</summary>
        private sealed class Group
        {
            private readonly string _folder;
            private readonly Dictionary<string, Sprite> _cache = new Dictionary<string, Sprite>();

            public Group(string folder)
            {
                _folder = Root + folder + "/";
            }

            public Sprite Get(string icon)
            {
                if (string.IsNullOrEmpty(icon))
                {
                    return null;
                }
                if (!_cache.TryGetValue(icon, out Sprite sprite))
                {
                    sprite = Load(_folder + icon);
                    _cache[icon] = sprite;   // a missing icon is remembered too: no repeated search
                }
                return sprite;
            }

            private static Sprite Load(string path)
            {
                Sprite sprite = Resources.Load<Sprite>(path);
                if (sprite != null)
                {
                    return sprite;
                }
                // The picture is imported as a plain texture (import settings were reset): wrap it.
                Texture2D texture = Resources.Load<Texture2D>(path);
                return texture == null
                    ? null
                    : Sprite.Create(texture, new Rect(0f, 0f, texture.width, texture.height), new Vector2(0.5f, 0.5f), PixelsPerUnit, 0, SpriteMeshType.FullRect);
            }
        }
    }
}
